package com.citacloud.springboot.contacloud.app.services;

import com.citacloud.springboot.contacloud.app.dto.*;
import com.citacloud.springboot.contacloud.app.models.*;
import com.citacloud.springboot.contacloud.app.repositories.*;
import com.citacloud.springboot.contacloud.app.security.*;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.orm.ObjectOptimisticLockingFailureException;
import org.springframework.security.access.prepost.PreAuthorize;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.*;import java.text.Normalizer;import java.util.*;

@Service
public class ConfiguracionDescuentoService {
    private final ConfiguracionDescuentoVentaRepository configuraciones;private final LimiteDescuentoRolRepository limites;
    private final MotivoDescuentoVentaRepository motivos;private final RolRepository roles;private final MonedaRepository monedas;
    private final AuditoriaService auditoria;
    public ConfiguracionDescuentoService(ConfiguracionDescuentoVentaRepository configuraciones,LimiteDescuentoRolRepository limites,
            MotivoDescuentoVentaRepository motivos,RolRepository roles,MonedaRepository monedas,AuditoriaService auditoria){this.configuraciones=configuraciones;this.limites=limites;this.motivos=motivos;this.roles=roles;this.monedas=monedas;this.auditoria=auditoria;}

    @Transactional
    @PreAuthorize("@empresaModuloService.habilitado('VENTAS') and hasAuthority('descuentos_configuracion.ver')")
    public ConfiguracionDescuentoDto obtener(){var p=TenantContext.principalActual();UUID empresa=EmpresaContext.requerirEmpresaId();ConfiguracionDescuentoVenta c=asegurar(p.tenantId(),empresa,p.usuarioId());return dto(c,p.tenantId(),empresa);}

    @Transactional
    @PreAuthorize("@empresaModuloService.habilitado('VENTAS') and hasAuthority('descuentos_configuracion.editar')")
    public ConfiguracionDescuentoDto guardarPolitica(ConfiguracionDescuentoInput input){if(input==null)throw new ReglaNegocioException("La configuración es obligatoria.");if(input.habilitado()&&(!input.permiteVenta()&&!input.permiteLinea()))throw new ReglaNegocioException("Debe habilitar al menos un alcance de descuento: venta completa o productos.");if(input.habilitado()&&(!input.permitePorcentaje()&&!input.permiteMonto()))throw new ReglaNegocioException("Debe habilitar al menos un tipo de descuento: porcentaje o monto.");var p=TenantContext.principalActual();UUID empresa=EmpresaContext.requerirEmpresaId();ConfiguracionDescuentoVenta c=asegurar(p.tenantId(),empresa,p.usuarioId());if(c.getVersion()!=input.version())throw new ReglaNegocioException("La configuración fue modificada por otro usuario. Actualiza la pantalla.");c.actualizar(input.habilitado(),input.permiteVenta(),input.permiteLinea(),input.permitePorcentaje(),input.permiteMonto(),input.requiereMotivo(),input.permiteAutorizacion(),p.usuarioId());try{configuraciones.saveAndFlush(c);}catch(ObjectOptimisticLockingFailureException ex){throw new ReglaNegocioException("La configuración fue modificada por otro usuario. Actualiza la pantalla.",ex);}auditoria.registrar("SALES_DISCOUNT_CONFIGURATION_UPDATED","ConfiguracionDescuentoVenta",c.getId(),"{}");return dto(c,p.tenantId(),empresa);}

    @Transactional
    @PreAuthorize("@empresaModuloService.habilitado('VENTAS') and hasAuthority('descuentos_configuracion.editar')")
    public void guardarLimite(UUID id,LimiteDescuentoInput input){if(input==null||input.rolId()==null)throw new ReglaNegocioException("Selecciona un rol.");BigDecimal porcentaje=porcentaje(input.porcentajeMaximo());BigDecimal monto=monto(input.montoMaximo());if(porcentaje==null&&monto==null)throw new ReglaNegocioException("Indica al menos un límite porcentual o monetario.");var p=TenantContext.principalActual();UUID empresa=EmpresaContext.requerirEmpresaId();Rol rol=roles.findByIdAndEmpresaId(input.rolId(),empresa).filter(Rol::isActivo).orElseThrow(()->new ReglaNegocioException("El rol seleccionado no está disponible."));LimiteDescuentoRol limite;if(id==null){if(limites.existsByTenantIdAndEmpresaIdAndRolId(p.tenantId(),empresa,rol.getId()))throw new ReglaNegocioException("El rol ya tiene límites configurados.");limite=new LimiteDescuentoRol(p.tenantId(),empresa,rol.getId(),porcentaje,monto,p.usuarioId());}else{limite=limites.findByIdAndTenantIdAndEmpresaId(id,p.tenantId(),empresa).orElseThrow(()->new RecursoNoEncontradoException("Límite no encontrado."));if(input.version()==null||limite.getVersion()!=input.version())throw new ReglaNegocioException("El límite fue modificado por otro usuario.");if(!limite.getRolId().equals(rol.getId()))throw new ReglaNegocioException("El rol de un límite existente no puede cambiarse.");limite.actualizar(porcentaje,monto,input.activo(),p.usuarioId());}try{limite=limites.saveAndFlush(limite);}catch(DataIntegrityViolationException ex){throw new ReglaNegocioException("El rol ya tiene límites configurados.",ex);}auditoria.registrar(id==null?"SALES_DISCOUNT_ROLE_LIMIT_CREATED":"SALES_DISCOUNT_ROLE_LIMIT_UPDATED","LimiteDescuentoRol",limite.getId(),"{\"rolId\":\""+rol.getId()+"\"}");}

    @Transactional
    @PreAuthorize("@empresaModuloService.habilitado('VENTAS') and hasAuthority('descuentos_configuracion.editar')")
    public void guardarMotivo(UUID id,MotivoDescuentoInput input){if(input==null)throw new ReglaNegocioException("Los datos del motivo son obligatorios.");String nombre=texto(input.nombre(),120,"El nombre del motivo es obligatorio.");String normalizado=normalizar(nombre);var p=TenantContext.principalActual();UUID empresa=EmpresaContext.requerirEmpresaId();MotivoDescuentoVenta motivo;if(id==null){if(motivos.existsByTenantIdAndEmpresaIdAndNombreNormalizado(p.tenantId(),empresa,normalizado))throw new ReglaNegocioException("El motivo ya existe.");motivo=new MotivoDescuentoVenta(p.tenantId(),empresa,nombre,normalizado,input.otro(),p.usuarioId());}else{motivo=motivos.findByIdAndTenantIdAndEmpresaId(id,p.tenantId(),empresa).orElseThrow(()->new RecursoNoEncontradoException("Motivo no encontrado."));if(input.version()==null||motivo.getVersion()!=input.version())throw new ReglaNegocioException("El motivo fue modificado por otro usuario.");if(motivos.existsByTenantIdAndEmpresaIdAndNombreNormalizadoAndIdNot(p.tenantId(),empresa,normalizado,id))throw new ReglaNegocioException("El motivo ya existe.");motivo.actualizar(nombre,normalizado,input.otro(),input.activo(),p.usuarioId());}try{motivo=motivos.saveAndFlush(motivo);}catch(DataIntegrityViolationException ex){throw new ReglaNegocioException("El motivo ya existe.",ex);}auditoria.registrar(id==null?"SALES_DISCOUNT_REASON_CREATED":"SALES_DISCOUNT_REASON_UPDATED","MotivoDescuentoVenta",motivo.getId(),"{}");}

    ConfiguracionDescuentoVenta asegurar(UUID tenant,UUID empresa,UUID usuario){return configuraciones.findByTenantIdAndEmpresaId(tenant,empresa).orElseGet(()->configuraciones.saveAndFlush(new ConfiguracionDescuentoVenta(tenant,empresa,usuario)));}
    private ConfiguracionDescuentoDto dto(ConfiguracionDescuentoVenta c,UUID tenant,UUID empresa){String moneda=monedas.findByEmpresaIdAndMonedaBaseTrue(empresa).map(Moneda::getCodigoIso).orElse("—");List<ConfiguracionDescuentoDto.Limite> ls=limites.findAllByTenantIdAndEmpresaIdOrderByRolNombre(tenant,empresa).stream().map(x->new ConfiguracionDescuentoDto.Limite(x.getId(),x.getRolId(),x.getRol().getNombre(),x.getPorcentajeMaximo(),x.getMontoMaximo(),x.isActivo(),x.getVersion())).toList();List<ConfiguracionDescuentoDto.Motivo> ms=motivos.findAllByTenantIdAndEmpresaIdOrderByNombre(tenant,empresa).stream().map(x->new ConfiguracionDescuentoDto.Motivo(x.getId(),x.getNombre(),x.isOtro(),x.isActivo(),x.getVersion())).toList();List<ConfiguracionDescuentoDto.RolOpcion> rs=roles.findAllByEmpresaIdAndActivoTrueOrderByNombre(empresa).stream().map(x->new ConfiguracionDescuentoDto.RolOpcion(x.getId(),x.getNombre())).toList();return new ConfiguracionDescuentoDto(c.isEnabled(),c.isPermiteVenta(),c.isPermiteLinea(),c.isPermitePorcentaje(),c.isPermiteMonto(),c.isRequiereMotivo(),c.isPermiteAutorizacion(),c.getVersion(),moneda,ls,ms,rs);}
    private static BigDecimal porcentaje(BigDecimal v){if(v==null)return null;v=v.setScale(4,RoundingMode.HALF_UP);if(v.signum()<0||v.compareTo(new BigDecimal("100"))>0)throw new ReglaNegocioException("El porcentaje debe estar entre 0 y 100.");return v;}
    private static BigDecimal monto(BigDecimal v){if(v==null)return null;v=v.setScale(4,RoundingMode.HALF_UP);if(v.signum()<0)throw new ReglaNegocioException("El monto máximo no puede ser negativo.");return v;}
    private static String texto(String v,int max,String requerido){String x=v==null?"":v.trim();if(x.isEmpty())throw new ReglaNegocioException(requerido);if(x.length()>max)throw new ReglaNegocioException("El nombre excede "+max+" caracteres.");return x;}
    private static String normalizar(String v){return Normalizer.normalize(v,Normalizer.Form.NFD).replaceAll("\\p{M}","").toLowerCase(Locale.ROOT).replaceAll("\\s+"," ").trim();}
}
